from pathlib import Path
p=Path('index.html');s=p.read_text(encoding='utf-8-sig')
s=s.replace('  <script defer src="assets/network/app.js"></script>', '  <script defer src="assets/network/materials-store.js"></script>\n  <script defer src="assets/network/public-materials.js"></script>\n  <script defer src="assets/network/materials-page.js"></script>\n  <script defer src="assets/network/app.js"></script>')
s=s.replace('      <a href="#plan" data-view="plan">', '      <a href="#materials" data-view="materials"><span aria-hidden="true">▥</span> 시험 자료</a>\n      <a href="#plan" data-view="plan">')
p.write_text(s,encoding='utf-8')
p=Path('assets/network/app.js');s=p.read_text(encoding='utf-8-sig')
s=s.replace("function route(){const", "function route(){window.StudyMaterialsPage?.unmount();const")
s=s.replace("['dashboard','keywords','commands','theory','quiz','wrong','plan']", "['dashboard','keywords','commands','theory','quiz','wrong','plan','materials']")
s=s.replace('wrong:wrongView,plan:renderPlan}', 'wrong:wrongView,plan:renderPlan,materials:()=>window.StudyMaterialsPage.mount({root:main,toast,confirmAction})}')
s=s.replace("plan:'14일 학습 계획'}[currentView]", "plan:'14일 학습 계획',materials:'시험 자료'}[currentView]")
s=s.replace('<section class="panel routine-panel"><div class="section-heading">','<a class="materials-dashboard-link" href="#materials"><strong>시험 자료</strong><span>회차별 문제·해설 파일을 드래그해서 추가</span><b aria-hidden="true">→</b></a>\n <section class="panel routine-panel"><div class="section-heading">')
p.write_text(s,encoding='utf-8')
p=Path('assets/network/materials-page.js');s=p.read_text(encoding='utf-8-sig')
s=s.replace("const allRecords = () => [...locals.map(r => ({...r, local:true})), ...published.map(r => ({...r, local:false}))];", "const allRecords = () => [...new Map([...published.map(r => ({...r,local:false})),...locals.map(r => ({...r,local:true}))].map(r=>[r.id,r])).values()];")
s=s.replace('max="2200"','max="2199"').replace('maxlength="160"','maxlength="200"')
s=s.replace('disabled = busy || Boolean(storageError)', 'disabled = busy || loading || Boolean(storageError)')
s=s.replace("await S.packagePublishing([...published,...locals])", "await S.packagePublishing(allRecords())")
s=s.replace("if (locals.some(r=>r.digest===digest))", "if (locals.some(r=>r.digest===digest || (!window.crypto?.subtle && r.filename===file.name && r.size===file.size)))")
p.write_text(s,encoding='utf-8')
public=Path('assets/network/public-materials.js')
if not public.exists():public.write_text('/* 公開用ファイル一覧 / 게시용 ZIP의 같은 파일로 교체하면 공개 자료가 추가됩니다. */\nwindow.PUBLIC_MATERIALS = [];\n',encoding='utf-8')
